export async function syncPrs(db: Database, list: () => Promise<PrRow[]>): Promise<{ rows: number }> {
  let rows: PrRow[];
  try {
    rows = await list();
  } catch (err) {
    throw new Error(`syncPrs: failed to list PRs: ${(err as Error).message ?? String(err)}`);
  }
  const tx = db.transaction(() => { for (const r of rows) upsertPr(db, r); });
  try {
    tx();
  } catch (err) {
    throw new Error(`syncPrs: failed to upsert PRs: ${(err as Error).message ?? String(err)}`);
  }
  return { rows: rows.length };
}

